// ---------- 1. Jobs (from Get Approved Jobs), one request per job ----------
const jobs = $('Get Approved Jobs').all().map(i => i.json).filter(j => j && j.id);
if (!jobs.length) {
  return []; // nothing approved yet, so the workflow stops here
}

// ---------- 2. Profile rows (from Get Profile), de-duplicated by id ----------
const get = (p, keys) => {
  for (const k of keys) {
    if (p[k] !== undefined && p[k] !== null && String(p[k]).trim() !== '') return String(p[k]);
  }
  return '';
};

const byId = new Map();
$input.all().map(i => i.json).filter(p => p.id).forEach(p => byId.set(p.id, p));
const profileRows = [...byId.values()];

const PROFILE = profileRows.map(p => {
  return [
    'EXPERIENCE: ' + get(p, ['name', 'property_name']),
    'Employer: ' + get(p, ['property_employer']),
    'Role: ' + get(p, ['property_role']),
    'Dates: ' + get(p, ['property_dates']),
    'What I did: ' + get(p, ['property_what_i_did']),
    'Result (X): ' + get(p, ['property_result_x']),
    'Metric (Y): ' + get(p, ['property_metric_y']),
    'How (Z): ' + get(p, ['property_how_z']),
    'Tools: ' + get(p, ['property_tools'])
  ].join('\n');
}).join('\n\n---\n\n');

// ---------- 3. Instructions for Claude ----------
const SYSTEM = `You are an expert CV writer and career coach. You help a candidate apply for Business Analyst, Project Coordinator, PMO and Project Assistant roles.

LANGUAGE
- Write ALL output in English, even if the job posting is in German or another language.

HARD RULES FOR THE CV
- Use ONLY facts and numbers that appear in the CANDIDATE PROFILE. Never invent employers, tools, numbers, dates or results.
- Never change the underlying facts. You may strengthen the wording only.
- Use job-posting keywords only to describe tasks the candidate really did. Put keywords that do not match real tasks into the cover letter instead (and only if they are true).
- If a metric is missing (time saved, speed, revenue, scale, accuracy), do not guess. Ask about it in "questions_for_candidate".
- Every bullet uses the Google XYZ format: "Accomplished [X], as measured by [Y], by doing [Z]." If no real metric exists for a task, write the bullet as a clear, honest description of what was done and the outcome, without inventing a number.

BULLET COUNT AND STRUCTURE
- Write 8 to 9 bullets in total, across the three employers: Employer A, Employer B, Employer C.
- Each employer gets 2 to 4 bullets. Never fewer than 2 per employer.
- Put the most job-relevant bullets first within each employer.
- If an employer's experience is closely connected to the job description, use 3 to 4 bullets for it.
- If an employer's experience is only loosely connected, still write 2 to 3 bullets for it. Include simpler everyday tasks (reporting, coordination, documentation, communication, process work, tools used), described honestly and linked to skills the job asks for.
- Never invent tasks or results.

PROFESSIONAL SUMMARY
- Write 3 to 4 sentences in the first person without "I" (CV style), tailored to this job.
- Use only facts from the CANDIDATE PROFILE. Mention the most relevant strengths and one or two real numbers.
- Do not copy the job posting. Do not use clichés.

COVER LETTER
- 230 to 280 words, in English, in 4 or 5 short paragraphs, separated by \\n\\n.
- Open with the employer's problem, not with "I am applying for".
- Show how the candidate has solved a similar problem, with one or two real numbers from the profile.
- Mention relevant keywords that did not fit into the CV bullets, but only if they are true.
- End with a clear, short invitation to talk. No clichés.

EMPLOYER PROBLEMS
- Name exactly 3 concrete problems the employer likely needs solved with this hire. Base them on the job description.

INTERVIEW TALKING POINTS
- Give exactly 3. Each links one employer problem to a real story or result from the profile.

OUTPUT FORMAT
Return ONLY a valid JSON object, with no text before or after it, with exactly these keys:
- "professional_summary": a single string, 3 to 4 sentences.
- "cv_bullets": a flat array of plain strings, 8 to 9 items. Each string is one bullet and MUST start with exactly one of these three prefixes: "Employer A, <role>: ", "Employer B, <role>: ", or "Employer C, <role>: ", followed by the bullet text. Group the bullets by employer in this order: Employer A, Employer B, Employer C. Do not use nested objects or sub-lists.
- "cover_letter": a single string.
- "employer_problems": an array of 3 plain strings.
- "talking_points": an array of 3 plain strings.
- "questions_for_candidate": an array of plain strings, with questions about missing metrics or facts.

JSON rules: use double quotes only. Put a comma between items. After a closing ] or } write only a comma or the end of the object. Do not write any other character, such as a parenthesis. Do not use real line breaks inside a string. Use \\n instead.`;

// ---------- 4. One request per job ----------
const out = [];
for (const job of jobs) {
  const description = String(job.property_raw_job_description || '').slice(0, 5000);

  // Skip LinkedIn jobs whose real description was never pasted in
  if (!description.trim() || /Imported from a LinkedIn/i.test(description)) continue;

  const user =
    'JOB TITLE: ' + (job.name || '') + '\n' +
    'LOCATION: ' + (job.property_location || '') + '\n' +
    'JOB DESCRIPTION:\n' + description + '\n\n' +
    'CANDIDATE PROFILE:\n' + PROFILE;

  out.push({
    json: {
      job_id: job.id,
      job_title: job.name || '',
      body: {
        model: 'claude-sonnet-5-5',
        max_tokens: 8000,
        thinking: { type: 'between_tools' },
        system: SYSTEM,
        messages: [{ role: 'user', content: user }]
      }
    }
  });
}

return out;

const src = $('Build Application Prompt').itemMatching($itemIndex).json;
const resp = $json;

let text = '';
if (Array.isArray(resp.content)) {
  text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
} else {
  text = String(resp.text || resp.data || '');
}

let parsed = false;
let r = {};
try {
  const s = text.indexOf('{');
  const e = text.lastIndexOf('}');
  r = JSON.parse(text.slice(s, e + 1));
  parsed = true;
} catch (err) {
  r = {};
}

const cut = (s, n = 1990) => String(s || '').slice(0, n);

const toList = (v) => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  return String(v || '').split('\n').map(x => x.trim()).filter(Boolean);
};

const clean = (s) => String(s).replace(/^[-•*\d.)\s]+/, '').trim();

const numbered = (v) => toList(v).map((x, i) => (i + 1) + '. ' + clean(x)).join('\n');

const bullets = toList(r.cv_bullets || r.bullets);

const group = (re) => bullets
  .filter(b => re.test(clean(b)))
  .map(b => clean(b).replace(/^[^:]{0,80}:\s*/, ''));

const employerA = group(/^employer a/i);
const employerB = group(/^employer b/i);
const employerC = group(/^employer c/i);

const summaryKey = Object.keys(r).find(k => /summary/i.test(k) && r[k]);
let summary = summaryKey ? r[summaryKey] : '';
if (Array.isArray(summary)) summary = summary.join(' ');
summary = String(summary || '').trim();

const coverLetter = String(r.cover_letter || '').trim();
const problems = numbered(r.employer_problems);
const points = numbered(r.talking_points);
const questions = numbered(r.questions_for_candidate || r.questions);

return {
  json: {
    job_id: src.job_id,
    job_title: src.job_title,
    parsed_ok: parsed,
    claude_keys: Object.keys(r).join(', '),
    cv_bullets: cut(bullets.map(clean).join('\n')),
    cover_letter: cut(coverLetter),
    employer_problems: cut(problems),
    talking_points: cut(points),
    questions: cut(questions),
    summary: summary,
    employer_a_bullets: employerA.join('\n'),
    employer_b_bullets: employerB.join('\n'),
    employer_c_bullets: employerC.join('\n'),
    cover_letter_full: coverLetter,
    employer_problems_full: problems,
    talking_points_full: points,
    questions_full: questions
  }
};

const items = $('Parse Materials').all();
const jobs = $('Get Approved Jobs').all().map(i => i.json);
const byId = {};
jobs.forEach(j => { if (j.id) byId[j.id] = j; });
const today = $now.toFormat('dd-MM-yyyy');

const out = [];
for (const item of items) {
  const r = item.json;
  const title = r.job_title || 'Job';
  const j = byId[r.job_id] || {};

  const notes =
    'JOB IDENTIFICATION\n' +
    'Job: ' + title + '\n' +
    'Location: ' + String(j.property_location || '') + '\n' +
    'Job posting: ' + String(j.property_job_url || j.property_url || '') + '\n' +
    'Notion page: ' + String(j.url || '') + '\n' +
    'Source: ' + String(j.property_source || '') + '\n' +
    'Pre-score: ' + String(j.property_pre_score == null ? '' : j.property_pre_score) + '\n' +
    'Claude verdict: ' + String(j.property_claude_verdict || '') + '\n' +
    'Materials created: ' + today + '\n\n' +

    'INTERVIEW PREPARATION\n\n' +
    'What the employer likely needs\n' + String(r.employer_problems_full || '') + '\n\n' +
    'Your talking points\n' + String(r.talking_points_full || '') + '\n\n' +
    'Questions to answer before sending\n' + String(r.questions_full || '') + '\n';

  out.push({ json: {
    job_title: title,
    cv_title: ('CV - ' + title + ' - ' + today).slice(0, 100),
    cover_title: ('Cover letter - ' + title + ' - ' + today).slice(0, 100),
    notes_title: ('Notes and interview prep - ' + title + ' - ' + today).slice(0, 100),
    summary: r.summary,
    employer_a_bullets: r.employer_a_bullets,
    employer_b_bullets: r.employer_b_bullets,
    employer_c_bullets: r.employer_c_bullets,
    cover_letter_text: String(r.cover_letter_full || ''),
    notes_text: notes
  } });
}
return out;
